vec2 glassHash(vec2 p) {
 vec3 p3=fract(vec3(p.x,p.y,p.x)*.1031);
 p3+=dot(p3,p3.yzx+33.33);
 return fract((p3.xx+p3.yz)*p3.zy);
}
// Jitter, stagger, row spacing and rotation for eight morphable cuts.
vec4 glassProfile(float shape) {
 if(shape<.5)return vec4(.75,0.,1.,0.);
 if(shape<1.5)return vec4(0.,.5,.8660254,0.);
 if(shape<2.5)return vec4(0.,0.,1.,0.);
 if(shape<3.5)return vec4(0.,0.,1.,.78539816);
 if(shape<4.5)return vec4(0.,.5,1.,0.);
 if(shape<5.5)return vec4(0.,.5,.8660254,.78539816);
 if(shape<6.5)return vec4(.16,0.,1.,0.);
 return vec4(.82,0.,1.,-.50);
}
float glassStretch(float shape) {
 if(shape<3.5)return 1.;
 if(shape<4.5)return .68;
 if(shape<5.5)return .70;
 if(shape<6.5)return 1.75;
 return 1.90;
}
vec2 glassSite(vec2 cell,vec4 profile) {
 vec2 random=glassHash(cell);
 vec2 site=vec2(cell.x+profile.y*mod(cell.y,2.),cell.y*profile.z)+(.5-profile.y)+(random-.5)*profile.x;
 float selected=smoothstep(.58,.94,glassHash(cell+19.7).x);
 return site+(random-.5)*((uParam_depth-.32)*.50+uParam_accent*selected*.32);
}
void mainImage(out vec4 fragColor,in vec2 fragCoord) {
 vec2 uv=fragCoord/iResolution.xy;
 vec4 original=vrchSampleSource0(uv);
 vec2 grid=iResolution.xy/min(iResolution.x,iResolution.y)*uParam_blocks;
 float shapeA=floor(uParam_shape),shapeB=min(7.,shapeA+1.);
 float shapeBlend=fract(uParam_shape);
 vec4 profile=mix(glassProfile(shapeA),glassProfile(shapeB),shapeBlend);
 float stretch=mix(glassStretch(shapeA),glassStretch(shapeB),shapeBlend);
 mat2 rotation=mat2(cos(profile.w),-sin(profile.w),sin(profile.w),cos(profile.w));
 mat2 basis=mat2(stretch,0.,0.,1./stretch)*rotation;
 mat2 inverseBasis=transpose(rotation)*mat2(1./stretch,0.,0.,stretch);
 vec2 p=basis*((uv-.5)*grid);
 vec2 cell=floor(vec2(p.x,p.y/profile.z));
 // One 3x3 search keeps the three nearest sites; the cut edge is the nearer
 // bisector to the second and third site.
 vec2 nearest=vec2(0.),second=vec2(0.),third=vec2(0.),owner=cell;
 float nearestDistance=100.,secondDistance=100.,thirdDistance=100.;
 for(int y=0;y<3;y++)for(int x=0;x<3;x++) {
  vec2 candidate=cell+vec2(float(x-1),float(y-1));
  vec2 delta=glassSite(candidate,profile)-p;
  float distance=dot(delta,delta);
  if(distance<nearestDistance){thirdDistance=secondDistance;third=second;secondDistance=nearestDistance;second=nearest;nearestDistance=distance;nearest=delta;owner=candidate;}
  else if(distance<secondDistance){thirdDistance=secondDistance;third=second;secondDistance=distance;second=delta;}
  else if(distance<thirdDistance){thirdDistance=distance;third=delta;}
 }
 float edgeDistance=100.;vec2 edgeNormal=vec2(1.,0.);
 vec2 between=second-nearest;
 if(dot(between,between)>.0001){edgeNormal=normalize(between);edgeDistance=dot(.5*(nearest+second),edgeNormal);}
 between=third-nearest;
 if(dot(between,between)>.0001){vec2 normal=normalize(between);float distance=dot(.5*(nearest+third),normal);if(distance<edgeDistance){edgeDistance=distance;edgeNormal=normal;}}
 vec2 local=-nearest,identity=glassHash(owner+19.7);
 float cellPixels=min(iResolution.x,iResolution.y)/uParam_blocks;
 float facetVisibility=smoothstep(3.,14.,cellPixels);
 float edgeVisibility=smoothstep(2.5,9.,cellPixels);
 float bevel=exp(-max(edgeDistance,0.)*20.);
 float aa=max(fwidth(edgeDistance),.001);
 float seam=1.-smoothstep(.003,.010+aa,edgeDistance);
 vec2 tilt=(identity-.5)*.28;
 vec2 bend=(local*.06+edgeNormal*bevel*.08+tilt*.15)*uParam_depth;
 vec2 imageUV=uv+(inverseBasis*bend)/grid;
 float selected=smoothstep(.58,.94,identity.x);
 float attack=uParam_accent*selected;
 float turn=(uParam_shine-.22)*1.65+(identity.x-.5)*attack*.90;
 vec2 crystalTilt=vec2(cos(turn+identity.y*6.28),sin(turn+identity.y*6.28));
 vec2 siteUV=uv+(inverseBasis*(nearest+crystalTilt*((uParam_shine-.22)*.48+attack*.20)))/grid;
 vec3 color=vrchSampleSource0(siteUV).rgb*.40;
 color+=(vrchSampleSource0(siteUV+vec2(.18,.12)/grid).rgb+vrchSampleSource0(siteUV+vec2(-.18,-.12)/grid).rgb+vrchSampleSource0(siteUV+vec2(-.12,.18)/grid).rgb+vrchSampleSource0(siteUV+vec2(.12,-.18)/grid).rgb)*.15;
 color=mix(color,vrchSampleSource0(imageUV).rgb,.02+uParam_depth*.06);
 float luminance=dot(color,vec3(.2126,.7152,.0722));
 color=max(vec3(.003),mix(vec3(luminance),color,1.25));
 color=pow(color,vec3(.94));
 // Stable triangular cut faces; music changes their light, never a time sweep.
 vec2 apex=(identity-.5)*((uParam_depth-.32)*.70+attack*.42);
 vec2 cutLocal=local-apex;
 float angle=atan(cutLocal.y,cutLocal.x)+turn;
 float cut=floor((angle+3.14159265)/2.0943951);
 float face=cos(cut*2.0943951+.65+identity.y*.3);
 float facetShade=1.+face*(.08+uParam_depth*.34)*(.30+.70*facetVisibility);
 float innerCut=pow(abs(sin((angle+3.14159265)*1.5)),.5);
 float litEdge=max(0.,dot(edgeNormal,normalize(vec2(-.6,.8))));
 vec3 lightColor=mix(color,vec3(1.,.96,.88),.12);
 vec3 result=color*facetShade*(.94+uParam_shine*(.22+.38*max(face,0.)));
 result+=lightColor*(bevel*(.06+litEdge*uParam_edges*.54)*edgeVisibility+attack*(.18+.28*max(face,0.)));
 result+=vec3(.18,.40,.65)*uParam_dispersion*bevel*litEdge*.20*edgeVisibility;
 result*=1.-(1.-innerCut)*uParam_depth*.05*facetVisibility;
 result=mix(result,color*.66+lightColor*(uParam_edges*.18+attack*.20),seam*.45*edgeVisibility);
 // Gentle highlight compression preserves color in bright glass.
 result/=1.+max(0.,max(result.r,max(result.g,result.b))-.75)*.16;
 fragColor=vec4(mix(original.rgb,result,uParam_amount),original.a);
}
